import { DynamoDBClient, GetItemCommand, PutItemCommand, UpdateItemCommand } from "@aws-sdk/client-dynamodb";
import { quotaExceeded } from "./problems.mjs";

// The cap on Spaces created without a coupon.
//
// Two paths create a Space (and so an S3 bucket) without a coupon: an
// unlock Space, whose id is derived from the signing did:key (any key
// holder, no account needed: this is how a FreeWallet client binds a
// passphrase or passkey), and, with the OpenProvisioning parameter on,
// any Space created by id. Both draw on one global counter kept in the
// registry table under a sentinel key, reserved with a conditional
// increment before the bucket is created and released when such a Space
// is deleted. Past the cap (`MAX_COUPONLESS_SPACES`, default 200) the
// creation is the spec's 507 quota-exceeded; a cap of 0 closes both paths.
// Spaces created with a coupon (`POST /spaces/`, an account Space) and the
// Spaces created under one (`POST /space/{s}/spaces`), which is how our own
// wallet and the batch issuer create every Space, never count.
//
// The registry row records how a Space was provisioned (`provisioning`):
// "coupon" (an account Space, created with a registration code), "account"
// (created under an account Space, at POST /space/{s}/spaces), "derived"
// and "open" (the two coupon-less paths). Rows from before this attribute
// existed are read by their id form: a server-assigned id was
// coupon-created, anything else was an unlock Space. The feed sweep
// recounts from the rows and backfills the attribute.

const dynamo = new DynamoDBClient({});
const SPACES_TABLE = process.env.SPACES_TABLE_NAME ?? "pws-spaces";

export const COUNTER_KEY = "urn:pws-server:couponless-spaces";

export const maxCouponlessSpaces = () => Number(process.env.MAX_COUPONLESS_SPACES ?? "200");

const SERVER_ASSIGNED_ID_RE = /^dcc-pws-[0-9a-f-]{36}$/;

export const isCounterRow = (row) => row?.spaceURL?.S === COUNTER_KEY;

// How a registry row's Space was provisioned, for rows with and without
// the attribute.
export function provisioningOf(row) {
  const recorded = row?.provisioning?.S;
  if (recorded !== undefined) {
    return recorded;
  }
  const id = row?.spaceURL?.S?.split("/space/")[1];
  return typeof id === "string" && !SERVER_ASSIGNED_ID_RE.test(id) ? "derived" : "coupon";
}

// The two paths any key holder can take, which the cap counts.
const COUPONLESS = new Set(["derived", "open"]);

export const isCouponlessRow = (row) => !isCounterRow(row) && COUPONLESS.has(provisioningOf(row));

// An account Space: one a coupon was spent on. Its controller may create
// further Spaces under it without a coupon.
export const isAccountRow = (row) => Boolean(row) && !isCounterRow(row) && provisioningOf(row) === "coupon";

const counterKey = () => ({ spaceURL: { S: COUNTER_KEY } });

// Takes one slot under the cap, or throws the 507.
export async function reserveCouponlessSlot({ max = maxCouponlessSpaces() } = {}) {
  const refusal = () => quotaExceeded(`This server creates at most ${max} Spaces without a coupon, and that many exist.`);
  if (!(max > 0)) {
    throw refusal();
  }
  try {
    await dynamo.send(
      new UpdateItemCommand({
        TableName: SPACES_TABLE,
        Key: counterKey(),
        UpdateExpression: "ADD #count :one",
        ConditionExpression: "attribute_not_exists(#count) OR #count < :max",
        ExpressionAttributeNames: { "#count": "count" },
        ExpressionAttributeValues: { ":one": { N: "1" }, ":max": { N: String(max) } },
      })
    );
  } catch (err) {
    if (err?.name === "ConditionalCheckFailedException") {
      throw refusal();
    }
    throw err;
  }
}

// Gives a slot back (a deleted coupon-less Space, or a creation that
// failed after reserving); never below zero.
export async function releaseCouponlessSlot() {
  try {
    await dynamo.send(
      new UpdateItemCommand({
        TableName: SPACES_TABLE,
        Key: counterKey(),
        UpdateExpression: "ADD #count :minus",
        ConditionExpression: "#count > :zero",
        ExpressionAttributeNames: { "#count": "count" },
        ExpressionAttributeValues: { ":minus": { N: "-1" }, ":zero": { N: "0" } },
      })
    );
  } catch (err) {
    if (err?.name !== "ConditionalCheckFailedException") {
      throw err;
    }
  }
}

export async function readCouponlessCount() {
  const { Item } = await dynamo.send(new GetItemCommand({ TableName: SPACES_TABLE, Key: counterKey() }));
  return Number(Item?.count?.N ?? 0);
}

export async function setCouponlessCount(count) {
  await dynamo.send(new PutItemCommand({ TableName: SPACES_TABLE, Item: { ...counterKey(), count: { N: String(count) } } }));
}

// --- The limit on the Spaces of one account ----------------------------------
//
// An account Space's controller creates further Spaces under it
// (POST /space/{s}/spaces) with no coupon. How many of those may exist at
// once is capped per account (`MAX_SPACES_PER_ACCOUNT`, default 100; a cap
// of 0 closes the route). The account Space's own registry row carries the
// count (`accountSpaces`), reserved with a conditional increment before the
// bucket is created and given back when such a Space is deleted or its
// creation fails. Past the cap the creation is the spec's 507
// quota-exceeded.
//
// What counts is every Space whose row names the account (`account`). The
// account Space itself does not, nor do Spaces an account created with a
// coupon of their own before 2026-11-19, which no row ties to it. The feed
// sweep recounts from the rows.

export const maxSpacesPerAccount = () => Number(process.env.MAX_SPACES_PER_ACCOUNT ?? "100");

const ACCOUNT_COUNT = "accountSpaces";

// How many Spaces an account Space's row says exist under it.
export const accountSpaceCountOf = (row) => Number(row?.[ACCOUNT_COUNT]?.N ?? 0);

// The account Space a row's Space was created under (its registry URL), or
// undefined for a Space that was not created under one.
export const accountOf = (row) => row?.account?.S;

const accountKey = (accountUrl) => ({ spaceURL: { S: accountUrl } });

// Takes one place under the account's limit, or throws the 507. The row
// must exist: an account Space deleted a moment ago gets no row back.
export async function reserveAccountSpace(accountUrl, { max = maxSpacesPerAccount() } = {}) {
  const refusal = () =>
    quotaExceeded(
      max > 0
        ? `This account already holds ${max} Spaces created under it, the most this server allows. Delete one to create another.`
        : "This server creates no Spaces under an account."
    );
  if (!(max > 0)) {
    throw refusal();
  }
  try {
    await dynamo.send(
      new UpdateItemCommand({
        TableName: SPACES_TABLE,
        Key: accountKey(accountUrl),
        UpdateExpression: "ADD #spaces :one",
        ConditionExpression: "attribute_exists(spaceURL) AND (attribute_not_exists(#spaces) OR #spaces < :max)",
        ExpressionAttributeNames: { "#spaces": ACCOUNT_COUNT },
        ExpressionAttributeValues: { ":one": { N: "1" }, ":max": { N: String(max) } },
      })
    );
  } catch (err) {
    if (err?.name === "ConditionalCheckFailedException") {
      throw refusal();
    }
    throw err;
  }
}

// Gives a place back (a deleted Space of the account, or a creation that
// failed after reserving); never below zero, and never on a row that is
// gone (the account Space was deleted before the Spaces under it).
export async function releaseAccountSpace(accountUrl) {
  try {
    await dynamo.send(
      new UpdateItemCommand({
        TableName: SPACES_TABLE,
        Key: accountKey(accountUrl),
        UpdateExpression: "ADD #spaces :minus",
        ConditionExpression: "#spaces > :zero",
        ExpressionAttributeNames: { "#spaces": ACCOUNT_COUNT },
        ExpressionAttributeValues: { ":minus": { N: "-1" }, ":zero": { N: "0" } },
      })
    );
  } catch (err) {
    if (err?.name !== "ConditionalCheckFailedException") {
      throw err;
    }
  }
}

// Sets an account's count to what a recount found (the feed sweep). A row
// that is gone stays gone; resolves to whether the row was written.
export async function setAccountSpaceCount(accountUrl, count) {
  try {
    await dynamo.send(
      new UpdateItemCommand({
        TableName: SPACES_TABLE,
        Key: accountKey(accountUrl),
        UpdateExpression: "SET #spaces = :count",
        ConditionExpression: "attribute_exists(spaceURL)",
        ExpressionAttributeNames: { "#spaces": ACCOUNT_COUNT },
        ExpressionAttributeValues: { ":count": { N: String(count) } },
      })
    );
    return true;
  } catch (err) {
    if (err?.name === "ConditionalCheckFailedException") {
      return false;
    }
    throw err;
  }
}
